\section{Introduction}

\subsection{The question}

Classical lossless compression is bounded by counting: over an alphabet of size
$q$ there are $q^n$ words of length $n$, and no injective encoding shortens them
all. But a great deal of real-world data is not drawn from that uniform pool. It
is the output of a short deterministic program: terrain in a procedurally
generated world, noise fields in a renderer, particle initial conditions in a
simulation, keystreams in a legacy protocol, padding in certain container
formats. Such a file is, information-theoretically, its seed.

The programme is therefore fourfold: \emph{fingerprint} (decide which generator
family, if any, produced the stream), \emph{recover} (invert to a seed),
\emph{certify} (prove the recovered seed reproduces the file exactly), and
\emph{route} (classify each file as seed-compressible or model-compressible).
This paper supplies unconditional mathematics for all four steps and delimits
how much the programme can possibly buy.

\subsection{Contributions}

\begin{itemize}[leftmargin=1.4em]
  \item A generic framework for seed-compressibility (Section~\ref{sec:framework}),
        with a pigeonhole capacity ceiling, a false-positive density bound, an
        exact-reproduction decoder guarantee, and eventual periodicity of
        finite-state generators.
  \item A complete analysis of the LFSR family (Section~\ref{sec:lfsr}).
  \item The reduction of linear congruential generators to order-two LFSRs
        (Section~\ref{sec:lcg}).
  \item The $2L$ theorem and its sharpness (Section~\ref{sec:2L}), with a Hankel
        criterion for tap uniqueness.
  \item Exact and improved enumeration of the linear-complexity filtration
        (Section~\ref{sec:counting}).
  \item Router capacity (Section~\ref{sec:router}).
  \item A verified recovery procedure and the maximal-complexity obstruction
        (Section~\ref{sec:recovery}).
  \item Noise tolerance: refutation of $2L+2e+1$, the corrected $2L(2e+1)$
        threshold, and its sharpness (Section~\ref{sec:noise}).
\end{itemize}

Throughout, $K$ is a commutative ring (a finite field where counting is
involved), $q = |K|$, and $L$ the order of a register.

\section{Seed-compressibility: the generic framework}\label{sec:framework}

\begin{definition}
A \emph{deterministic pseudorandom generator} with state space $S$ and output
alphabet $\alpha$ is a pair $g = (\stepmap, \out)$ with $\stepmap : S \to S$ and
$\out : S \to \alpha$.
\end{definition}

\begin{definition}
The \emph{stream} of $g$ from seed $s$ is
$\str_g(s)(t) = \out(\stepmap^{t}(s))$, $t \in \NN$; its length-$n$
\emph{prefix} is $\pref_g^n(s) = (\str_g(s)(0), \dots, \str_g(s)(n-1))$.
\end{definition}

Two identities used repeatedly: $\str_g(s)(t+1) = \str_g(\stepmap(s))(t)$ and
$\str_g(s)(t+k) = \str_g(\stepmap^{t}(s))(k)$.

\begin{definition}
A word $x \in \alpha^n$ is \emph{seed-compressible} for $g$ if
$\pref_g^n(s) = x$ for some $s \in S$. Write $C_g(n) \subseteq \alpha^n$ for the
set of such words.
\end{definition}

Seed-compressibility is the falsifiability gate of the whole programme: the
decompressed output must equal the file in every position, with no tolerance.

\begin{theorem}[Capacity ceiling]\label{thm:ceiling}
For every $n$, $|C_g(n)| \le |S|$.
\end{theorem}

\begin{proof}
$C_g(n)$ is the image of $\pref_g^n : S \to \alpha^n$, and the image of a map is
no larger than its domain.
\end{proof}

\begin{corollary}
If $|S| < |\alpha|^n$ then some word of length $n$ is not seed-compressible for
$g$; and the fraction of length-$n$ words accepted by a perfect detector is at
most $|S|/|\alpha|^n$.
\end{corollary}

\begin{theorem}[Extrapolation soundness]
If $\pref_g^n$ is injective and $\pref_g^n(s) = \pref_g^n(s')$ then
$\str_g(s)(t) = \str_g(s')(t)$ for all $t$; in that case the decoder is unique.
\end{theorem}

\begin{theorem}[Eventual periodicity]
Let $|S| < \infty$ and $s \in S$. There exist $i \ge 0$ and $p \ge 1$ with
$i + p \le |S|$ and $\stepmap^{i+p}(s) = \stepmap^{i}(s)$. Consequently
$\str_g(s)(t+kp) = \str_g(s)(t)$ for $t \ge i$, and the entire stream is
determined by its first $|S|$ symbols.
\end{theorem}

\begin{proof}
The $|S|+1$ states $\stepmap^{0}(s), \dots, \stepmap^{|S|}(s)$ cannot be
distinct; the earliest collision gives preperiod $i$ and period $p$ with
$i+p \le |S|$. Any index $t \ge i$ reduces modulo $p$ into $[i, i+p)$, and every
index $t < i$ already lies in $[0,|S|)$.
\end{proof}

This is the structural reason a seed certifies an arbitrarily long file.

\section{Linear feedback shift registers}\label{sec:lfsr}

\begin{definition}
Fix $L \ge 1$ and a \emph{tap vector} $c \in K^L$. The \emph{Fibonacci LFSR} with
taps $c$ has state space $K^L$; its step map sends $\sigma$ to $\sigma'$ with
$\sigma'_i = \sigma_{i+1}$ for $i < L-1$ and $\sigma'_{L-1} = \sum_{j<L} c_j
\sigma_j$; its output map is $\out(\sigma) = \sigma_0$. Write $\str_c(\sigma)$
for its stream.
\end{definition}

\begin{lemma}[Window lemma]\label{lem:window}
For all $i < L$, $k \ge 0$ and every seed $\sigma$,
$\bigl(\stepmap_c^{k}(\sigma)\bigr)_i = \str_c(\sigma)(i+k)$.
\end{lemma}

\begin{proof}
Induction on $i$. For $i=0$ this is the definition of the output map at the state
at time $k$. For the step, cell $i+1$ of the state at time $k$ equals cell $i$ of
the state at time $k+1$ (the boundary case $i+1=L$ does not arise since
$i+1<L$), so the hypothesis at $(i,k+1)$ gives $\str_c(\sigma)(i+k+1)$.
\end{proof}

\begin{corollary}[Seed $=$ prefix]\label{cor:seedprefix}
For $k<L$, $\str_c(\sigma)(k) = \sigma_k$. Hence $\pref_c^L(\sigma) = \sigma$: the
length-$L$ prefix map is the identity, in particular injective.
\end{corollary}

\begin{definition}
A sequence $y : \NN \to K$ \emph{satisfies the order-$L$ recurrence with taps
$c$}, written $\Rec_c(y)$, if
\[
  y_{t+L} \;=\; \sum_{j=0}^{L-1} c_j\, y_{t+j} \qquad \text{for all } t \ge 0 .
\]
The \emph{linear complexity} of a sequence is the least such $L$.
\end{definition}

\begin{theorem}[Fingerprint]\label{thm:fingerprint}
$\Rec_c(\str_c(\sigma))$ for every tap vector $c$ and seed $\sigma$.
\end{theorem}

\begin{proof}
Write $L = m+1$. By Lemma~\ref{lem:window}, cell $m$ of the state at time $t+1$
equals $\str_c(\sigma)(m+t+1) = \str_c(\sigma)(t+L)$. By definition of the step
map, that cell also equals $\sum_j c_j \bigl(\stepmap_c^{t}(\sigma)\bigr)_j$, and
Lemma~\ref{lem:window} rewrites each summand as $\str_c(\sigma)(t+j)$.
\end{proof}

\begin{theorem}[Detection is exact]\label{thm:detect}
For every sequence $y$,
\[
  \Rec_c(y) \iff \exists\, \sigma \in K^L,\ \forall t,\ \str_c(\sigma)(t) = y_t .
\]
\end{theorem}

\begin{proof}
($\Leftarrow$) is Theorem~\ref{thm:fingerprint}. For ($\Rightarrow$) take
$\sigma = (y_0,\dots,y_{L-1})$ and induct strongly on $t$: for $t<L$ apply
Corollary~\ref{cor:seedprefix}; for $t = t'+L$ apply
Theorem~\ref{thm:fingerprint} on the left and $\Rec_c(y)$ on the right, matching
the two sums termwise using the hypothesis at the smaller indices $t'+j$.
\end{proof}

Theorem~\ref{thm:detect} is simultaneously soundness and completeness of the
fingerprint test.

\begin{corollary}[Exact reproduction: the falsifiability gate]\label{cor:exactrep}
If $\Rec_c(y)$ then the seed $(y_0,\dots,y_{L-1})$ read off the first $L$ symbols
regenerates $y$ at every index, not merely on the observed window.
\end{corollary}

\section{Linear congruential generators are order-two LFSRs}\label{sec:lcg}

\begin{definition}
The \emph{linear congruential generator} with multiplier $a$ and increment $b$
has state space $K$, step map $x \mapsto ax+b$, and identity output map; its
stream satisfies $x_{t+1} = a x_t + b$.
\end{definition}

\begin{theorem}[Cross-family fingerprint]\label{thm:lcg}
For all $a,b,x_0 \in K$, the LCG stream satisfies the order-two recurrence with
taps $(-a,\,a+1)$:
\[
  x_{t+2} \;=\; (a+1)\,x_{t+1} \;-\; a\,x_t .
\]
\end{theorem}

\begin{proof}
Subtract $x_{t+1} = a x_t + b$ from $x_{t+2} = a x_{t+1} + b$ to get
$x_{t+2}-x_{t+1} = a(x_{t+1}-x_t)$.
\end{proof}

\begin{corollary}
The order-two LFSR with taps $(-a,a+1)$ and seed $(x_0,\, a x_0 + b)$ reproduces
the LCG stream at every index; two observed symbols suffice for recovery.
\end{corollary}

\begin{proposition}
Over a finite $K$ with $q$ elements, at most $q^3$ words of each length are LCG
output; hence for $n>3$ some length-$n$ word is produced by no LCG.
\end{proposition}

\section{The $2L$ theorem}\label{sec:2L}

\begin{theorem}[The $2L$ theorem]\label{thm:2L}
Let $K$ be a nontrivial commutative ring, $L \ge 1$, and let $y,z : \NN \to K$
satisfy $\Rec_c(y)$ and $\Rec_{c'}(z)$ for tap vectors $c,c' \in K^L$ that need
not be equal. If $y_t = z_t$ for all $t < 2L$, then $y = z$.
\end{theorem}

\begin{corollary}[Certified seed recovery]\label{cor:certified}
If two order-$L$ registers, with arbitrary taps and arbitrary seeds, produce the
same first $2L$ output symbols, their streams coincide at every time. An
order-$L$ generator recovered from $2L$ observed symbols provably reproduces the
rest of the file, however long.
\end{corollary}

\subsection{The polynomial module structure}

Let $\shift$ be the shift on sequences, $(\shift y)_t = y_{t+1}$. It is
$K$-linear, so $K^{\NN}$ is a $K[X]$-module with $X$ acting as $\shift$.

\begin{lemma}
$(\shift^{i} y)_t = y_{t+i}$, and for $p \in K[X]$ of degree $d$,
$\bigl(p(\shift)y\bigr)_t = \sum_{i=0}^{d} p_i\, y_{t+i}$. The action of a
polynomial is the associated linear recurrence operator.
\end{lemma}

\begin{definition}
For $c \in K^L$ the \emph{characteristic polynomial} is
$f_c(X) = X^L - \sum_{j=0}^{L-1} c_j X^j$.
\end{definition}

\begin{lemma}\label{lem:monic}
$\deg\bigl(\sum_j c_j X^j\bigr) < L$, so $f_c$ is monic; over a nontrivial ring
$\deg f_c = L$ exactly.
\end{lemma}

\begin{lemma}[Recurrence $=$ annihilation]\label{lem:annih}
$\Rec_c(y)$ holds if and only if $f_c(\shift)\,y = 0$.
\end{lemma}

\begin{proof}
$\bigl(f_c(\shift)y\bigr)_t = y_{t+L} - \sum_j c_j y_{t+j}$, which vanishes for
all $t$ exactly when the recurrence holds.
\end{proof}

\begin{lemma}[Rigidity]\label{lem:rigid}
Let $p \in K[X]$ be monic of degree $m$ and let $w : \NN \to K$ satisfy
$p(\shift)w = 0$ and $w_t = 0$ for all $t<m$. Then $w = 0$.
\end{lemma}

\begin{proof}
Strong induction on $t$. For $t<m$ the hypothesis applies. For $t = t'+m$ the
annihilation relation at $t'$ reads $\sum_{i=0}^{m} p_i w_{t'+i} = 0$; monicity
makes the top term $w_{t'+m}$ itself, and each lower term has index
$t'+i < t$ and vanishes by hypothesis.
\end{proof}

Monicity is essential: it is what lets the newest value be solved for, without
dividing by a leading coefficient.

\begin{lemma}[Annihilators multiply]\label{lem:mult}
If $f(\shift)y = 0$ and $g(\shift)z = 0$ then $(fg)(\shift)(y-z) = 0$.
\end{lemma}

\begin{proof}
Polynomials in the single operator $\shift$ commute, so
$(fg)(\shift)y = g(\shift)\bigl(f(\shift)y\bigr) = 0$ and likewise
$(fg)(\shift)z = 0$; subtract.
\end{proof}

This is the step where two \emph{different} tap vectors are merged into one
algebraic object.

\begin{proof}[Proof of Theorem~\ref{thm:2L}]
By Lemma~\ref{lem:annih}, $f_c(\shift)y = 0$ and $f_{c'}(\shift)z = 0$. By
Lemma~\ref{lem:mult}, $w = y-z$ is annihilated by $p = f_c f_{c'}$, which is
monic of degree $2L$ by Lemma~\ref{lem:monic}. The hypothesis says $w_t = 0$ for
$t < 2L = \deg p$, so Lemma~\ref{lem:rigid} gives $w = 0$.
\end{proof}

\subsection{Sharpness}

\begin{theorem}[$2L$ is sharp]\label{thm:sharp}
For every $L \ge 1$ and every nontrivial commutative ring $K$ there exist tap
vectors $c,c'$ and seeds $\sigma,\sigma' \in K^L$ whose streams agree at every
index $t < 2L-1$ and differ at $t = 2L-1$.
\end{theorem}

\begin{proof}
Take both seeds to be the impulse $\sigma = \sigma' = (0,\dots,0,1)$. With
$c = 0$ the register empties and the stream is $0^{L-1}\,1\,0\,0\cdots$. With
$c' = (1,0,\dots,0)$ the recurrence is the pure delay $y_{t+L}=y_t$ and the
stream is the periodic impulse train $0^{L-1}\,1\,0^{L-1}\,1\cdots$. For $t<L$
both equal $\sigma_t$; for $L \le t = t'+L < 2L-1$ we have $t'<L-1$ and both give
$0$; at $t = 2L-1 = (L-1)+L$ the first gives $0$ and the second gives
$\sigma_{L-1} = 1$.
\end{proof}

Hence no gate based on fewer than $2L$ observed symbols is sound.

\subsection{Tap uniqueness: the Hankel criterion}

\begin{definition}
The $L \times L$ \emph{Hankel matrix} of an observed window is $H_{t,j} =
y_{t+j}$, $0 \le t,j < L$.
\end{definition}

\begin{theorem}[Tap uniqueness]\label{thm:hankel}
Let $K$ be an integral domain and $\det H \ne 0$. If $\Rec_c(y)$ and
$\Rec_{c'}(y)$ then $c = c'$.
\end{theorem}

\begin{proof}
Subtracting the two recurrences at time $t<L$ gives $\sum_j y_{t+j}(c_j-c'_j)=0$,
i.e.\ $H(c-c') = 0$; nonsingularity forces $c = c'$.
\end{proof}

\section{Counting: how rare is low linear complexity?}\label{sec:counting}

Let $K$ be finite with $q = |K|$, let
$W_L(n) = \{\pref^n_c(\sigma) : c,\sigma \in K^L\} \subseteq K^n$ and
$N_L(n) = |W_L(n)|$.

\begin{theorem}[Rarity]
$N_L(n) \le q^{2L}$. Hence if $q \ge 2$ and $n > 2L$ some word of length $n$ is
in no $W_L(n)$, and the density $N_L(n)/q^n$ is at most $q^{2L-n}$.
\end{theorem}

\begin{theorem}[Nesting and hierarchy collapse]\label{thm:nesting}
Padding a tap vector with a leading zero turns an order-$L$ recurrence into an
order-$(L{+}1)$ recurrence for the same stream. Hence $W_L(n) \subseteq
W_{L+1}(n)$, and the set of words of linear complexity $\le M$ equals $W_M(n)$.
\end{theorem}

\begin{proof}
If $\Rec_c(y)$ then with $\tilde c = (0,c_0,\dots,c_{L-1})$ we get
$\sum_{j\le L}\tilde c_j y_{t+j} = \sum_{j<L} c_j y_{t+1+j} = y_{t+1+L}$.
\end{proof}

\begin{corollary}
If $q \ge 2$ and $n > 2M+1$ then some length-$n$ word is produced by no register
of order $\le M$: bounded-order seed compression is never universal.
\end{corollary}

\begin{theorem}[Saturation]\label{thm:sat}
For $n \ge 2L$, $N_L(n)$ does not depend on $n$.
\end{theorem}

\begin{proof}
Truncation $W_L(n') \to W_L(n)$ for $n' \ge n \ge 2L$ is surjective by
construction and injective by Theorem~\ref{thm:2L}.
\end{proof}

\begin{theorem}[Zero-seed collapse]\label{thm:zeroseed}
For all $L,n$, $N_L(n) \le q^{2L} - q^{L} + 1$; for $L \ge 1$, $q \ge 2$ this is
a strict improvement over $q^{2L}$.
\end{theorem}

\begin{proof}
Split the $q^{2L}$ parameter pairs into the $q^L$ with zero seed --- all of which
produce the same, all-zero, word, contributing at most $1$ --- and the remaining
$q^{2L}-q^L$.
\end{proof}

\begin{theorem}[Exact enumeration at order one]\label{thm:orderone}
Let $K$ be a finite field with $q$ elements and $n \ge 2$. Then
\[
  N_1(n) \;=\; q(q-1)+1 \;=\; q^2-q+1 .
\]
\end{theorem}

\begin{proof}
Over a field the order-one register is multiplication by its single tap $c$, so
its stream is the geometric sequence $y_t = c^t s$. If $s \ne 0$ the pair
$(s,c)$ is recoverable from the first two symbols ($s = y_0$, $c = y_1/y_0$), so
distinct such pairs give distinct words: $q(q-1)$ of them. If $s = 0$ the word is
all-zero for every $c$, contributing one more. The case distinction needs
$n \ge 2$, since one symbol cannot see $c$.
\end{proof}

\begin{corollary}
$q^{L} < N_1(n) < q^{2L}$ at $L=1$ for $q \ge 2$: neither general bound is tight.
The order-one count \emph{attains} the bound of Theorem~\ref{thm:zeroseed}, and
$N_1(n)(q+1) = q^3+1$, i.e.\ $N_1(n) = (q^3+1)/(q+1)$.
\end{corollary}

\begin{conjecture}\label{conj:C1}
For a finite field with $q$ elements, $L \ge 1$ and $n \ge 2L$,
\[
  N_L(n) \;=\; \frac{q^{2L+1}+1}{q+1}.
\]
\end{conjecture}

Exhaustive enumeration is strikingly obedient: over $q=2$, orders $L=1,\dots,5$
give $3, 11, 43, 171, 683$, matching $(2^{2L+1}+1)/3$; over $q=3$, orders
$L=1,2,3$ give $7, 61, 547$, matching $(3^{2L+1}+1)/4$. The values
$(q,L) = (2,1),(2,2),(2,3),(3,1),(3,2)$ have been confirmed by exhaustive
enumeration over the full parameter space, as has the saturation prediction
$N_2(4) = N_2(5) = 11$ over $q=2$. The case $L=1$ is Theorem~\ref{thm:orderone};
$L \ge 2$ is open. Note that at $q=2$, $L=2$ the bound of
Theorem~\ref{thm:zeroseed} gives $13$ against the true value $11$, so the
remaining slack is exactly the higher-order degeneracy the conjecture predicts.

\section{Router capacity: a Kraft-type ceiling}\label{sec:router}

A \emph{router} is a front end that inspects a file, selects any member of a
library of generator families, and emits a family index together with a seed.
Different members may have completely different state spaces.

\begin{definition}
Let $\iota$ be finite and, for $i \in \iota$, let $g_i$ be a generator with
finite state space $S_i$ and common output alphabet $\alpha$. The \emph{routed
words} of length $n$ are $\mathcal{R}(n) = \bigcup_{i} C_{g_i}(n)$.
\end{definition}

\begin{theorem}[Router capacity ceiling]\label{thm:router}
$\displaystyle |\mathcal{R}(n)| \;\le\; \sum_{i \in \iota} |S_i| .$
\end{theorem}

\begin{proof}
$|\mathcal{R}(n)| \le \sum_i |C_{g_i}(n)| \le \sum_i |S_i|$ by
Theorem~\ref{thm:ceiling}.
\end{proof}

\begin{corollary}
At least $|\alpha|^n - \sum_i |S_i|$ words of length $n$ are rejected by every
member; if $\sum_i |S_i| < |\alpha|^n$ then some word is routed nowhere; and the
false-positive density on uniform data is at most
$\bigl(\sum_i |S_i|\bigr)/|\alpha|^n$.
\end{corollary}

\begin{corollary}[A router that compresses everything saves nothing]
If every length-$n$ word is reproducible by some member, then
$|\alpha|^n \le \sum_i |S_i|$.
\end{corollary}

Adding families adds their seed counts and nothing more. There is no synergy:
detecting the generator buys code space only where the data distribution is far
from uniform, never on average.

\begin{proposition}
Over a finite field with $q$ elements and $n \ge 2$, the router over all
registers of order $\le 1$ carries $1+q^2$ seeds but accepts exactly $q^2-q+1$
words --- a deficit of exactly $q$.
\end{proposition}

\begin{proof}
By Theorem~\ref{thm:nesting} the routed set collapses onto the order-one family,
of size $q^2-q+1$ by Theorem~\ref{thm:orderone}; the seed budget is
$|K^0|^2 + |K^1|^2 = 1+q^2$.
\end{proof}

\section{A verified recovery procedure}\label{sec:recovery}

Given an observed word $x$ of length $n$ and a target order $L \le n$: set
$\hat\sigma = (x_0,\dots,x_{L-1})$ (by Corollary~\ref{cor:seedprefix} the only
candidate seed), let $T(x) = \{c \in K^L : \pref^n_c(\hat\sigma) = x\}$, and
accept iff $T(x) \ne \emptyset$.

\begin{theorem}[Soundness]
Every $c \in T(x)$ reproduces $x$ symbol by symbol from $\hat\sigma$.
\end{theorem}

\begin{theorem}[Completeness]\label{thm:complete}
$T(x) \ne \emptyset$ if and only if $x \in W_L(n)$.
\end{theorem}

\begin{proof}
If $\pref^n_c(\sigma) = x$ then by Corollary~\ref{cor:seedprefix} the first $L$
symbols of $x$ are $\sigma$, so $\sigma = \hat\sigma$ and $c \in T(x)$.
\end{proof}

Restricting the seed search to the observed window therefore loses nothing.

\begin{theorem}[Certified extrapolation]
If $n \ge 2L$ then all $c,c' \in T(x)$ generate the same infinite stream from
$\hat\sigma$.
\end{theorem}

\begin{proof}
Both streams satisfy order-$L$ recurrences and agree on the first $2L \le n$
symbols; apply Theorem~\ref{thm:2L}.
\end{proof}

\begin{definition}
The \emph{impulse word} of length $n$ is $(0,0,\dots,0,1)$.
\end{definition}

\begin{theorem}\label{thm:impulse}
Over a nontrivial ring, no register of order $L<n$ produces the impulse word,
while order $n$ does: its linear complexity is exactly $n$.
\end{theorem}

\begin{proof}
Its first $L$ symbols are all zero, so the only compatible seed is the zero seed,
which produces the all-zero word under every tap vector --- not the impulse word,
whose last symbol is $1$. At order $n$ the seed is the whole word.
\end{proof}

\begin{corollary}
It is \emph{not} true that a recovery routine can always return an order
$L \le \lceil n/2 \rceil$ consistent with the observed window: for $n \ge 2$ the
impulse word is consistent with no such order. The correct invariant is
minimality of the returned order.
\end{corollary}

\section{Noise tolerance}\label{sec:noise}

\begin{definition}
For an observed word $w$ of length $n$ and a candidate stream $y$, the
\emph{error set} is $E(w,y) = \{i<n : w_i \ne y_i\}$.
\end{definition}

The natural coding-theoretic guess is an additive threshold $n \ge 2L+2e+1$. It
is false.

\begin{theorem}[Refutation of the additive threshold]\label{thm:c4false}
For every $e \ge 1$ there exist two distinct sequences $y \ne z$ of linear
complexity one over $\FF_3$ and a word $w$ of length exactly $2\cdot 1 + 2e + 1$
with $|E(w,y)| \le e$ and $|E(w,z)| \le e$.
\end{theorem}

\begin{proof}
Over $\FF_3$, let $y_t = 1$ (order one, tap $1$) and $z_t = 2^t$ (order one, tap
$2$); since $2^2 = 1$, $z$ is $1$ at even $t$ and $2$ at odd $t$, so $y \ne z$.
Let $w$ have length $n = 2e+3$ with $w_1 = 2$ and $w_i = 1$ otherwise. Then
$E(w,y) = \{1\}$ and $E(w,z) = \{3,5,\dots,2e+1\}$, of sizes $1 \le e$ and $e$.
\end{proof}

The smallest instance is $e=1$, $n=5$. The failure is structural: $y$ and $z$
agree at every even index, so their disagreements are maximally spread and no
window of $2L$ consecutive positions is error-free.

\begin{lemma}[Shifted $2L$ theorem]\label{lem:shifted}
If $\Rec_c(y)$, $\Rec_{c'}(z)$ and $y_t = z_t$ for all $t$ in a block of $2L$
consecutive indices $[j, j+2L)$, then $y_t = z_t$ for all $t \ge j$.
\end{lemma}

\begin{proof}
Shifting preserves the recurrence; apply Theorem~\ref{thm:2L} to
$t \mapsto y_{t+j}$ and $t \mapsto z_{t+j}$.
\end{proof}

\begin{lemma}[Block pigeonhole]\label{lem:blocks}
Let $E \subseteq \{0,\dots,n-1\}$ with $|E| \le 2e$ and $n \ge 2L(2e+1)$. Then one
of the $2e+1$ disjoint blocks $[2Lm, 2L(m{+}1))$, $m = 0,\dots,2e$, misses $E$.
\end{lemma}

\begin{theorem}[Corrected threshold]\label{thm:c4prime}
Let $\Rec_c(y)$, $\Rec_{c'}(z)$, and let $w$ have length $n \ge 2L(2e+1)$ with
$|E(w,y)| \le e$ and $|E(w,z)| \le e$. Then there is $j$ with $j + 2L \le n$ and
$y_t = z_t$ for all $t \ge j$.
\end{theorem}

\begin{proof}
Set $E = E(w,y) \cup E(w,z)$, of size at most $2e$. By Lemma~\ref{lem:blocks}
pick a clean block $[2Lm, 2L(m{+}1))$ with $2L(m+1) \le n$. On it $w$ agrees with
both $y$ and $z$, so $y$ and $z$ agree on $2L$ consecutive indices;
Lemma~\ref{lem:shifted} with $j = 2Lm$ concludes.
\end{proof}

\begin{theorem}[Sharpness at order one]\label{thm:c4sharp}
For every $e$, at window length $4e+1 = 2\cdot 1 \cdot (2e+1) - 1$ unique decoding
already fails: some word of that length lies within Hamming distance $e$ of two
distinct order-one streams over $\FF_3$.
\end{theorem}

\begin{proof}
Take $y_t = 1$, $z_t = 2^t$ as above, and let $w$ of length $4e+1$ be $w_i = 1$
for even $i$; for odd $i$, $w_i = 1$ if $i < 2e$ and $w_i = 2$ otherwise. Even
indices agree with both. Of the $2e$ odd indices, the $e$ with $i<2e$ disagree
with $z$ only, and the $e$ with $i>2e$ disagree with $y$ only. Hence
$|E(w,y)| = |E(w,z)| = e$.
\end{proof}

Together, Theorems~\ref{thm:c4false}, \ref{thm:c4prime} and \ref{thm:c4sharp} pin
the truth at order one: the correct threshold for noise-tolerant fingerprinting
is not the linear $2L+2e+1$ but exactly the multiplicative $2L(2e+1)$.

\section{Algorithms}

\subsection*{Fingerprint and recover}
Input a word $x$ of length $n$ over a finite field and a maximum order $M$. For
$L = 0,1,\dots,M$: set $\hat\sigma = (x_0,\dots,x_{L-1})$; solve the linear system
$\sum_j c_j x_{t+j} = x_{t+L}$ for $0 \le t \le n-L-1$ ($O(nL^2)$ by Gaussian
elimination, or $O(n^2)$ for all orders at once by the Berlekamp--Massey
recurrence); if a solution exists, verify $\pref^n_c(\hat\sigma) = x$ and return
$(L, c, \hat\sigma)$. Otherwise report failure. Completeness is
Theorem~\ref{thm:complete}.

\subsection*{Certification}
Given $(L,c,\sigma)$ recovered from a window of length $n \ge 2L$,
Corollary~\ref{cor:certified} certifies that the recovered seed reproduces the
remainder of the file. If $n < 2L$, Theorem~\ref{thm:sharp} shows no certificate
is available at that length.

\subsection*{Noise-tolerant fingerprinting}
If at most $e$ symbols may be corrupted, take a window of length at least
$2L(2e+1)$ (Theorem~\ref{thm:c4prime}) and search the $2e+1$ disjoint length-$2L$
blocks; a clean block exists and the generator recovered from it is correct from
that point on. Do not use $2L+2e+1$ (Theorem~\ref{thm:c4false}).

\section{Discussion and future work}

The seed-compression programme cannot beat the pigeonhole bound, and
Theorem~\ref{thm:router} says so with no assumption on the generators; what it
can do is reallocate code space to a sparse structured corner of file space,
with a bit-exact gate. The $2L$ theorem is the certification statement behind the
Berlekamp--Massey attack on shift-register keystreams, here over an arbitrary
commutative ring and with an explicit sharpness witness; Theorem~\ref{thm:hankel}
is the precise condition for the recovered taps, not merely the recovered stream,
to be unique. The most practically consequential finding is the gap between
$2L+2e+1$ and $2L(2e+1)$: a detector on contaminated data needs a window growing
multiplicatively in the error budget.

Open questions: Conjecture~\ref{conj:C1} for $L \ge 2$; sharpness of $2L(2e+1)$
beyond order one; a recovery routine certified to return a \emph{minimal}
consistent order; certified inversion for nonlinear generator families (to which
Theorem~\ref{thm:router} applies unchanged); and an empirical corpus study of
what fraction of real files pass a bit-exact seed-compressibility gate.

